function s(ov){const o=oracle.parseSignup(ov),m=main.parseSignup(ov);return (o.ok?"ok":"ERR:"+JSON.stringify(o.problems))+"  ||  "+(m.ok?"ok":"ERR:"+JSON.stringify(m.problems));}
print("== ip (zoned ipv6) ==");
for(const ip of ["fe80::1%eth0","2001:db8::ff00:42:8329%wlan0","::%1","7e60::16eb%25","fe80::1%","%eth0","fe80::1%eth 0","fe80::1%../../etc","notanip%eth0","1.2.3.4%eth0","fe80::1"]) print(JSON.stringify(ip),"->",s({...base,ip}));
print("== age ==");
for(const age of [13,12,9007199254740991,9007199254740994,1e21,1.7976931348623157e308,2.5,-1]) print(age,"->",s({...base,age}));
print("== website value ==");
for(const website of ["https://example.com"," https://example.com","https://example.com\n","HTTPS://EXAMPLE.COM/A","https://example.com:443/x","https://example.com/a/../b","https://example.com/p?q=1#f","http://exa­mple.com","https://xn--bcher-kva.de","https://bücher.de"]){const o=oracle.parseSignup({...base,website}),m=main.parseSignup({...base,website});print(JSON.stringify(website),"->",o.ok?JSON.stringify(o.value.website):"ERR","||",m.ok?JSON.stringify(m.value.website):"ERR");}
