for(const z of ["fe80::1%eth0","FE80::1%ETH0","fe80::1%25eth0","fe80::1%a b","fe80::1%a\nb","fe80::1%../../etc/passwd","fe80::1%"+"x".repeat(200),"fe80::1%<script>alert(1)</script>","::1%eth0","2001:db8::1%wlan0","fe80:0000:0000:0000:0000:0000:0000:0001%eth0","fe80::1%zone%zone"]) cmp(JSON.stringify(z),{ip:z});
